//! Slovenian nouns the numerals agree with, from Sloleks 3.1 (CJVT,
//! CLARIN.SI, hdl 11356/2080, CC BY-SA 4.0). The tables are generated by
//! `tools/formant/slovenian_words.py`.

use crate::text::table;

/// Neuter nouns in -o, nominative and accusative singular (mesto, not the
/// feminine accusative nagrado).
static NEUTER_O: &str = include_str!("tables/neuter_o.txt");

/// Words in -a after the number 1 that are not a feminine nominative, with
/// their kind.
static NOUN_A: &str = include_str!("tables/noun_a.txt");

/// What a word in -a after the number 1 is, when it is not a feminine
/// nominative.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum NounA {
    /// A masculine noun's animate accusative, or a masculine or neuter noun's
    /// genitive singular (otroka: enega otroka).
    Genitive,
    /// A masculine noun's nominative (kolega: en kolega).
    Masculine,
}

/// True for a neuter noun in -o (tretje mesto, but tretjo nagrado).
pub fn is_neuter_noun_o(word: &str) -> bool {
    table::contains(NEUTER_O, word)
}

/// The kind of a word in -a that is not a feminine nominative.
pub fn noun_a_kind(word: &str) -> Option<NounA> {
    match table::lookup(NOUN_A, word)? {
        "1" => Some(NounA::Genitive),
        "2" => Some(NounA::Masculine),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables() {
        assert!(is_neuter_noun_o("mesto") && is_neuter_noun_o("abderitstvo") && !is_neuter_noun_o("nagrado"));
        assert_eq!(noun_a_kind("otroka"), Some(NounA::Genitive));
        assert_eq!(noun_a_kind("kolega"), Some(NounA::Masculine));
        assert_eq!(noun_a_kind("miza"), None);
    }
}
